<script setup lang="ts">
import {computed,ref} from 'vue';import {capturePosition} from './geolocation';import {api,display} from './api';import InfoFields from './InfoFields.vue';import TencentMap from './TencentMap.vue';
import {sourceLabels,statusLabels,certaintyLabels,type CandidateInput} from '../../shared/coordinates';
const props=defineProps<{place:any;continuous?:boolean}>(),emit=defineEmits<{changed:[]}>();
const active=computed(()=>props.place.coordinates.find((c:any)=>c.status==='active')||null);
const history=computed(()=>props.place.coordinates.filter((c:any)=>c.status!=='active'));
const busy=ref(false),error=ref(''),message=ref(''),mode=ref<'manual'|'map'>('map');
const latitude=ref(''),longitude=ref(''),system=ref<CandidateInput['coordinate_system']|''>(''),accuracy=ref(''),reference=ref(''),notes=ref('');
const certainty=ref<CandidateInput['position_certainty']|''>('');
const picked=ref<{latitude:number;longitude:number;source_time:string;source_reference:string}|null>(null);
const review=ref<any>(null),acknowledged=ref(false),rejection=ref<any>(null),reason=ref(''),revoking=ref(false),revokeId=ref<string|null>(null);
const fields={raw_latitude:'原始纬度',raw_longitude:'原始经度',raw_coordinate_system:'原始坐标系',map_latitude:'地图纬度',map_longitude:'地图经度',map_coordinate_system:'地图坐标系',source_label:'坐标来源',source_reference:'来源说明',certainty_label:'位置确定度',confidence_level:'来源依据等级（旧 A—D）',source_time:'采集时间',accuracy_display:'定位精度',conversion_method:'地图转换方法',created_at:'创建时间',confirmed_at:'人工确认时间',confirmed_by:'确认人',status_label:'状态'};
const shown=(c:any)=>({...c,certainty_label:certaintyLabels[c.position_certainty]||'未记录',map_latitude:c.map_latitude??c.converted_latitude,map_longitude:c.map_longitude??c.converted_longitude,source_label:sourceLabels[c.source_type]||c.source_type,status_label:statusLabels[c.status],accuracy_display:c.accuracy_meters===null?`未知（${c.accuracy_note||'未记录'}）`:`${c.accuracy_meters} 米`});
async function run(fn:()=>Promise<unknown>,success:string){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();message.value=success;review.value=null;rejection.value=null;revoking.value=false;emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function saveManual(){if(!String(latitude.value).trim()||!String(longitude.value).trim()){error.value='请填写纬度和经度';return;}if(!system.value){error.value='请选择坐标系';return;}if(!Number.isFinite(Number(latitude.value))||Math.abs(Number(latitude.value))>90||!Number.isFinite(Number(longitude.value))||Math.abs(Number(longitude.value))>180){error.value='纬度须为 -90 至 90，经度须为 -180 至 180 的有效数字';return;}await run(()=>api(`/places/${props.place.code}/coordinate-candidates`,{latitude:Number(latitude.value),longitude:Number(longitude.value),coordinate_system:system.value,accuracy_meters:accuracy.value===''?null:Number(accuracy.value),source_type:'manual_input',source_reference:reference.value,source_time:new Date().toISOString(),notes:notes.value,...(certainty.value?{position_certainty:certainty.value}:{})}),'已保存手工输入候选，尚未成为正式坐标。');}
async function saveMap(){if(!picked.value)return;if(!certainty.value){error.value='请选择位置确定度';return;}await run(async()=>{await api(`/places/${props.place.code}/coordinate-candidates`,{...picked.value,coordinate_system:'GCJ-02',accuracy_meters:null,source_type:'map_click',position_certainty:certainty.value,notes:notes.value});picked.value=null;},'已保存地图点选候选，尚未成为正式坐标。');}
async function locate(){
 if(!window.isSecureContext){error.value='手机定位需要 HTTPS。请通过可信 HTTPS 地址打开管理端；电脑 localhost 可直接测试。';return;}
 if(!navigator.geolocation){error.value='此浏览器不支持定位，请使用地图点选或手工输入。';return;}
 await run(async()=>{
  const code=props.place.code,assessment=certainty.value;const position=await capturePosition();
  const captured:CandidateInput={latitude:position.coords.latitude,longitude:position.coords.longitude,accuracy_meters:position.coords.accuracy,coordinate_system:'WGS84',source_type:'phone_gps',source_reference:'浏览器 navigator.geolocation',source_time:new Date(position.timestamp).toISOString(),...(assessment?{position_certainty:assessment}:{})};
  await api(`/places/${code}/coordinate-candidates`,captured);
 },'手机位置已保存为候选，请核对实际落点后确认。');
}
function openReview(c:any){review.value={...c,expected_current_id:active.value?.id||null};acknowledged.value=false;}
async function confirm(){await run(()=>api(`/places/${props.place.code}/coordinate-candidates/${review.value.id}/confirm`,{expected_current_id:review.value.expected_current_id,acknowledged:acknowledged.value}),'候选已确认；原有效坐标如存在，已保留为历史记录。');}
</script>
<template><section class="coordinate-manager"><h2>坐标管理</h2><p>以卫星影像人工判点为主，手机 GPS 可补充采集。所有坐标先保存候选，人工确认后才成为正式坐标。</p><p class="verification-summary">是否实地核验：{{place.verifications.length?'有实地核验记录（详见最新核验）':'未有实地核验记录'}}。卫星判点及坐标确认不会自动生成实地核验记录，也不代表地点开放或可正式导航。</p>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p>
 <div class="coordinate-block current-block" role="region" aria-label="当前正式坐标"><h3>当前正式坐标</h3><InfoFields v-if="active" :data="shown(active)" :fields="fields"/><p v-else>暂无当前有效正式坐标。</p>
 <button v-if="active" type="button" class="secondary" :disabled="busy" @click="revokeId=active.id;revoking=true;reason=''">撤销当前坐标</button>
 <form v-if="revoking" class="review-box" @submit.prevent="run(()=>api(`/places/${place.code}/coordinates/${revokeId}/revoke`,{reason,expected_current_id:revokeId}), '正式坐标已撤销，历史仍保留。')"><label>撤销原因<input v-model="reason" required maxlength="1000"></label><p>撤销后本地点从内部地图消失，不自动恢复旧坐标。</p><button :disabled="busy||!reason.trim()">确认撤销</button><button type="button" class="secondary" @click="revoking=false">取消</button></form>
 </div><div class="coordinate-block capture-block" role="region" aria-label="采集新候选"><h3>采集新候选</h3>
 <div class="actions"><button type="button" :class="mode==='manual'?'':'secondary'" @click="mode='manual'">手工输入</button><button type="button" :class="mode==='map'?'':'secondary'" @click="mode='map'">地图点选</button></div>
 <label class="certainty-input">位置确定度<select v-model="certainty" aria-label="位置确定度"><option disabled value="">请选择位置确定度</option><option v-for="(label,value) in certaintyLabels" :key="value" :value="value">{{label}}</option></select></label><p class="muted">位置确定度是你对落点的判断，不等于测量精度或实地核验；原 A—D 来源等级保持原定义，地图／卫星判点记录为 C 级。</p>
 <form v-if="mode==='manual'" class="coordinate-form" @submit.prevent="saveManual"><label>纬度<input v-model="latitude" required type="number" step="any" min="-90" max="90" inputmode="decimal"></label><label>经度<input v-model="longitude" required type="number" step="any" min="-180" max="180" inputmode="decimal"></label><label>坐标系<select v-model="system" required aria-label="坐标系"><option disabled value="">请选择坐标系</option><option>GCJ-02</option><option>WGS84</option><option>BD-09</option><option>未知</option></select></label><label>定位精度（米，未知留空）<input v-model="accuracy" type="number" step="any" min="0"></label><label>来源说明（可选）<input v-model="reference" maxlength="1000"></label><label>采集备注（可选）<input v-model="notes" maxlength="2000"></label><button :disabled="busy">保存手工候选</button></form>
 <div v-else><TencentMap pick :remember-view="continuous" :center="active?{latitude:active.map_latitude,longitude:active.map_longitude}:null" :selected="picked" @pick="point=>picked={...point,source_time:new Date().toISOString()}"/><p v-if="picked">选中：纬度 {{picked.latitude.toFixed(6)}}，经度 {{picked.longitude.toFixed(6)}} · GCJ-02 · 精度未知 · {{picked.source_reference}}</p><p class="muted">点击另一处可重选；取消选点不会写入数据。保存后仅建立候选。来源按点选时底图记录，之后切换底图不会改写已选位置的来源。</p><div class="actions"><button type="button" :disabled="!picked||busy" @click="saveMap">保存地图候选</button><button type="button" class="secondary" :disabled="!picked||busy" @click="picked=null">取消选点</button></div></div>
 <div class="gps-supplement"><h4>手机 GPS 补充采集</h4><p class="muted">仅在实际到达当前地点时使用。保留 WGS84 原值、浏览器精度和采集时间，需要位置权限与可信 HTTPS；同样只保存候选。</p><button type="button" :disabled="busy" @click="locate">{{busy?'正在处理…':'采集当前位置'}}</button></div>
 </div><div class="coordinate-block candidate-block" role="region" aria-label="候选坐标"><h3>候选坐标</h3><p v-if="!place.candidates.length">暂无坐标候选。</p><article v-for="c in place.candidates" :key="c.id" :data-candidate-id="c.id"><h4>{{c.code}} · {{statusLabels[c.status]}}</h4><InfoFields :data="shown(c)" :fields="fields"/><p v-if="c.rejected_reason">拒绝原因：{{c.rejected_reason}}</p><p v-if="c.notes">备注：{{c.notes}}</p><div v-if="c.status==='pending'" class="actions"><button type="button" :disabled="busy" @click="openReview(c)">{{active?'核对并替换正式坐标':'核对并确认候选'}}</button><button type="button" class="secondary" :disabled="busy" @click="rejection=c;reason=''">拒绝候选</button></div></article>
 <div v-if="review" role="dialog" aria-label="确认候选坐标" class="review-box"><h3>确认前核对</h3><p>地点：{{place.code}} {{place.name}} · {{place.public_level}}</p><p>当前正式地图坐标：{{active?`${active.map_latitude}, ${active.map_longitude} GCJ-02`:'无'}}</p><p>新候选原始坐标：{{review.raw_latitude}}, {{review.raw_longitude}} {{review.raw_coordinate_system}}</p><p>新地图坐标：{{display(review.converted_latitude)}}, {{display(review.converted_longitude)}} {{display(review.map_coordinate_system)}}</p><p>来源：{{sourceLabels[review.source_type]}} · {{display(review.source_reference)}} · 精度 {{review.accuracy_meters===null?'未知':review.accuracy_meters+' 米'}}</p><p v-if="['dji_srt','gps_track'].includes(review.source_type)">轨迹可能代表设备位置。请确认这是此地点实际可用落点，不能把无人机空中位置直接当作停车或下河入口。</p><p>位置确定度：{{certaintyLabels[review.position_certainty]||'未记录'}}。这是位置判断，不是实地核验。</p><p>确认后原 active 坐标变为 superseded 并保留。未知坐标系不能确认。</p><label class="checkbox"><input v-model="acknowledged" type="checkbox">我已人工核对地点、坐标系和落点</label><div class="actions"><button type="button" :disabled="busy||!acknowledged" @click="confirm">确认写入正式历史</button><button type="button" class="secondary" @click="review=null">取消</button></div></div>
 <form v-if="rejection" class="review-box" @submit.prevent="run(()=>api(`/places/${place.code}/coordinate-candidates/${rejection.id}/reject`,{reason}),'候选已拒绝，原始记录仍保留。')"><h3>拒绝 {{rejection.code}}</h3><label>拒绝原因<input v-model="reason" required maxlength="1000"></label><div class="actions"><button :disabled="busy||!reason.trim()">确认拒绝</button><button type="button" class="secondary" @click="rejection=null">取消</button></div></form>
 </div><div class="coordinate-block history-block" role="region" aria-label="历史坐标"><h3>历史坐标</h3><p class="muted">已替换和已撤销记录只读，不能编辑、删除或重新启用。</p><p v-if="!history.length">暂无已替换或已撤销记录。</p><article v-for="c in history" :key="c.id"><h4>{{statusLabels[c.status]}} · {{c.id}}</h4><InfoFields :data="shown(c)" :fields="{...fields,status_changed_at:'状态变更时间',revocation_reason:'撤销原因',revoked_by:'撤销人',revoked_at:'撤销时间',superseded_by:'替换后的记录'}"/></article>
</div></section></template>
